import { isLocalDate, isTaskRecord } from './domain.js';

export const DEFAULT_DAILY_BUDGET_MINUTES = 120;
export const MIN_DAILY_BUDGET_MINUTES = 5;
export const MAX_DAILY_BUDGET_MINUTES = 1440;

export function validateDailyPlan(input) {
  const errors = {};
  const date = input?.date;
  const taskIds = input?.taskIds;
  const budgetMinutes = input?.budgetMinutes ?? DEFAULT_DAILY_BUDGET_MINUTES;
  if (!isLocalDate(date)) errors.date = 'Choose a valid calendar date.';
  if (!Array.isArray(taskIds) || taskIds.some(id => typeof id !== 'string' || !id.trim() || id.length > 200)) {
    errors.taskIds = 'Choose valid tasks for this day.';
  } else if (new Set(taskIds).size !== taskIds.length) {
    errors.taskIds = 'A task can only be planned once per day.';
  }
  if (!Number.isInteger(budgetMinutes) || budgetMinutes < MIN_DAILY_BUDGET_MINUTES || budgetMinutes > MAX_DAILY_BUDGET_MINUTES) {
    errors.budgetMinutes = `Enter a whole number from ${MIN_DAILY_BUDGET_MINUTES} to ${MAX_DAILY_BUDGET_MINUTES}.`;
  }
  return { errors, value: { date, taskIds: Array.isArray(taskIds) ? [...taskIds] : taskIds, budgetMinutes } };
}

function validated(input) {
  const result = validateDailyPlan(input);
  if (Object.keys(result.errors).length) throw new Error(Object.values(result.errors).join(' '));
  return result.value;
}

export function createDailyPlan(input) {
  return validated(input);
}

export function isDailyPlanRecord(plan) {
  if (!plan || typeof plan !== 'object' || Array.isArray(plan)) return false;
  if (!['date', 'taskIds', 'budgetMinutes'].every(key => Object.hasOwn(plan, key))) return false;
  const result = validateDailyPlan(plan);
  return Object.keys(result.errors).length === 0
    && result.value.date === plan.date
    && result.value.budgetMinutes === plan.budgetMinutes
    && result.value.taskIds.length === plan.taskIds.length
    && result.value.taskIds.every((id, index) => id === plan.taskIds[index]);
}

export function dailyPlanRecord(plan) {
  return { date: plan.date, taskIds: [...plan.taskIds], budgetMinutes: plan.budgetMinutes };
}

export function dailyPlanSummary(plan, tasks) {
  if (!isDailyPlanRecord(plan)) throw new Error('The daily plan is invalid.');
  if (!Array.isArray(tasks) || tasks.some(task => !isTaskRecord(task))) throw new Error('The task list is invalid.');
  const tasksById = new Map(tasks.map(task => [task.id, task]));
  const plannedTasks = plan.taskIds.map(id => tasksById.get(id)).filter(Boolean);
  const missingTaskIds = plan.taskIds.filter(id => !tasksById.has(id));
  const plannedMinutes = plannedTasks.reduce((total, task) => total + task.estimatedMinutes, 0);
  const completedTasks = plannedTasks.filter(task => task.completed);
  const completedMinutes = completedTasks.reduce((total, task) => total + task.estimatedMinutes, 0);
  const remainingMinutes = plan.budgetMinutes - plannedMinutes;
  return {
    tasks: plannedTasks,
    missingTaskIds,
    taskCount: plannedTasks.length,
    completedTaskCount: completedTasks.length,
    plannedMinutes,
    completedMinutes,
    budgetMinutes: plan.budgetMinutes,
    timeLeftMinutes: Math.max(0, remainingMinutes),
    overBudgetMinutes: Math.max(0, -remainingMinutes)
  };
}
import test from 'node:test';
import assert from 'node:assert/strict';
import { createTask, setTaskCompleted } from '../src/domain.js';
import { createDailyPlan, dailyPlanSummary, isDailyPlanRecord, validateDailyPlan } from '../src/daily-plan.js';

const timestamp = '2026-09-24T12:00:00.000Z';
const write = createTask({ title: 'Write brief', notes: '', priority: 'High', dueDate: null, estimatedMinutes: 45 }, { id: 'write', now: timestamp });
const review = createTask({ title: 'Review brief', notes: '', priority: 'Medium', dueDate: null, estimatedMinutes: 30 }, { id: 'review', now: timestamp });

test('creates a dated plan with an ordered task selection and a 120-minute default budget', () => {
  const plan = createDailyPlan({ date: '2026-10-03', taskIds: ['review', 'write'] });
  assert.deepEqual(plan, { date: '2026-10-03', taskIds: ['review', 'write'], budgetMinutes: 120 });
  assert.equal(isDailyPlanRecord(plan), true);
});

test('rejects invalid plan dates, duplicate tasks, and out-of-range budgets', () => {
  const result = validateDailyPlan({ date: '2026-02-29', taskIds: ['write', 'write'], budgetMinutes: 1441 });
  assert.deepEqual(Object.keys(result.errors).sort(), ['budgetMinutes', 'date', 'taskIds']);
  assert.throws(() => createDailyPlan({ date: '2026-10-03', taskIds: [], budgetMinutes: 4 }), /whole number/);
});

test('calculates workload, over-budget time, and task completion from current tasks', () => {
  const plan = createDailyPlan({ date: '2026-10-03', taskIds: ['review', 'write'], budgetMinutes: 60 });
  const summary = dailyPlanSummary(plan, [write, setTaskCompleted(review, true, timestamp)]);
  assert.deepEqual(summary, {
    tasks: [setTaskCompleted(review, true, timestamp), write],
    missingTaskIds: [],
    taskCount: 2,
    completedTaskCount: 1,
    plannedMinutes: 75,
    completedMinutes: 30,
    budgetMinutes: 60,
    timeLeftMinutes: 0,
    overBudgetMinutes: 15
  });
});

test('keeps a plan readable when a planned task has since been deleted', () => {
  const plan = createDailyPlan({ date: '2026-10-03', taskIds: ['write', 'removed'], budgetMinutes: 120 });
  const summary = dailyPlanSummary(plan, [write]);
  assert.deepEqual(summary.missingTaskIds, ['removed']);
  assert.equal(summary.plannedMinutes, 45);
  assert.equal(summary.timeLeftMinutes, 75);
});
import test from 'node:test';
import assert from 'node:assert/strict';
import { createTask } from '../src/domain.js';
import { createFocusSession, finishFocusSession } from '../src/focus.js';
import { createDailyPlan } from '../src/daily-plan.js';
import { DAILY_PLAN_STORAGE_KEY, DAILY_PLAN_STORAGE_VERSION, FOCUS_STORAGE_KEY, FOCUS_STORAGE_VERSION, loadDailyPlans, loadFocusData, loadTasks, saveDailyPlans, saveFocusData, saveTasks, STORAGE_KEY, STORAGE_VERSION } from '../src/storage.js';

function memoryStorage(initial = {}) {
  const values = new Map(Object.entries(initial));
  return { getItem: key => values.get(key) ?? null, setItem: (key, value) => values.set(key, value), values };
}

const task = createTask({ title: 'Review brief', notes: '', priority: 'Medium', dueDate: null, estimatedMinutes: 25 }, { id: 'task-1', now: '2026-09-24T12:00:00.000Z' });

test('saves a versioned record and restores valid tasks', () => {
  const storage = memoryStorage();
  assert.deepEqual(saveTasks(storage, [task]), { ok: true, message: '' });
  assert.deepEqual(loadTasks(storage), { tasks: [task], writable: true, message: '' });
  assert.equal(JSON.parse(storage.values.get(STORAGE_KEY)).version, STORAGE_VERSION);
});

test('preserves damaged or unsupported data by disabling editing', () => {
  const damaged = loadTasks(memoryStorage({ [STORAGE_KEY]: '{not json' }));
  const unsupported = loadTasks(memoryStorage({ [STORAGE_KEY]: JSON.stringify({ version: 99, tasks: [] }) }));
  assert.equal(damaged.writable, false);
  assert.match(damaged.message, /damaged/);
  assert.equal(unsupported.writable, false);
  assert.match(unsupported.message, /unsupported/);
});

test('skips invalid records without overwriting valid stored data', () => {
  const storage = memoryStorage({ [STORAGE_KEY]: JSON.stringify({ version: STORAGE_VERSION, tasks: [task, { ...task, id: 'task-1' }, { id: 'bad' }] }) });
  const loaded = loadTasks(storage);
  assert.deepEqual(loaded.tasks, [task]);
  assert.equal(loaded.writable, false);
  assert.match(loaded.message, /invalid or duplicate/);
});

test('reports storage write failures', () => {
  const storage = { getItem: () => null, setItem: () => { throw new Error('blocked'); } };
  assert.deepEqual(saveTasks(storage, [task]), { ok: false, message: 'Could not save to this browser. Storage may be full or blocked. No changes were applied. Your form is kept open so you can retry.' });
});

test('saves and restores an active focus session with retained history', () => {
  const storage = memoryStorage();
  const active = createFocusSession(task, 25, { id: 'focus-1', now: '2026-09-24T12:00:00.000Z' });
  const previous = createFocusSession(task, 25, { id: 'focus-0', now: '2026-09-24T11:00:00.000Z' });
  const history = [finishFocusSession(previous, 'finishedEarly', '2026-09-24T11:05:00.000Z')];
  assert.deepEqual(saveFocusData(storage, active, history), { ok: true, message: '' });
  assert.deepEqual(loadFocusData(storage), { activeSession: active, history, writable: true, message: '' });
  assert.equal(JSON.parse(storage.values.get(FOCUS_STORAGE_KEY)).version, FOCUS_STORAGE_VERSION);
  assert.deepEqual(saveFocusData(storage, active, [finishFocusSession(active, 'cancelled', '2026-09-24T12:05:00.000Z')]), { ok: false, message: 'These focus sessions could not be saved because their records are duplicated. No changes were applied.' });
});

test('preserves damaged focus data by disabling focus controls', () => {
  const damaged = loadFocusData(memoryStorage({ [FOCUS_STORAGE_KEY]: '{not json' }));
  const invalid = loadFocusData(memoryStorage({ [FOCUS_STORAGE_KEY]: JSON.stringify({ version: FOCUS_STORAGE_VERSION, activeSession: null, history: [{ id: 'bad' }] }) }));
  assert.equal(damaged.writable, false);
  assert.match(damaged.message, /damaged/);
  assert.equal(invalid.writable, false);
  assert.match(invalid.message, /invalid/);
});

test('saves dated daily plans and preserves invalid plan data without overwriting it', () => {
  const storage = memoryStorage();
  const plan = createDailyPlan({ date: '2026-10-03', taskIds: [task.id], budgetMinutes: 120 });
  assert.deepEqual(saveDailyPlans(storage, [plan]), { ok: true, message: '' });
  assert.deepEqual(loadDailyPlans(storage), { plans: [plan], writable: true, message: '' });
  assert.equal(JSON.parse(storage.values.get(DAILY_PLAN_STORAGE_KEY)).version, DAILY_PLAN_STORAGE_VERSION);
  const invalid = loadDailyPlans(memoryStorage({ [DAILY_PLAN_STORAGE_KEY]: JSON.stringify({ version: DAILY_PLAN_STORAGE_VERSION, plans: [plan, { ...plan }] }) }));
  assert.equal(invalid.writable, false);
  assert.match(invalid.message, /duplicate/);
});

test('reports daily-plan storage write failures', () => {
  const storage = { getItem: () => null, setItem: () => { throw new Error('blocked'); } };
  const plan = createDailyPlan({ date: '2026-10-03', taskIds: [], budgetMinutes: 120 });
  assert.deepEqual(saveDailyPlans(storage, [plan]), { ok: false, message: 'Could not save daily plans to this browser. Storage may be full or blocked. No changes were applied.' });
});

